<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableCodeVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableTenantVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableTypeVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableValueVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableEnabledVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableVersionVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Application\Usecase\Disable\TemplateVariableDisableResult;
use PHPUnit\Framework\TestCase;

final class TemplateVariableDisableResultUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new TemplateVariableDisableResult();
        $codeOneValue = 'one';
        $codeOtherValue = 'other';
        $copy = $value->code($codeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getCode());
        $this->assertNotEquals('other', $value->getCode());
        $this->assertEquals('one', $value->getCodeOrCurrent(TemplateVariableCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('other', $value->getCodeOrCurrent(TemplateVariableCodeVO::from($codeOtherValue))->value());
        $value->unsetCode();
        $this->assertEquals('other', $value->getCodeOrCurrent(TemplateVariableCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('one', $value->getCodeOrCurrent(TemplateVariableCodeVO::from($codeOtherValue))->value());
        $tenantOneValue = new TenantRef('one');
        $tenantOtherValue = new TenantRef('other');
        $copy = $value->tenant($tenantOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TenantRef('one'), $value->getTenant());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenant());
        $this->assertEquals(new TenantRef('one'), $value->getTenantOrCurrent(TemplateVariableTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenantOrCurrent(TemplateVariableTenantVO::from($tenantOtherValue))->value());
        $value->unsetTenant();
        $this->assertEquals(new TenantRef('other'), $value->getTenantOrCurrent(TemplateVariableTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('one'), $value->getTenantOrCurrent(TemplateVariableTenantVO::from($tenantOtherValue))->value());
        $typeOneValue = 'one';
        $typeOtherValue = 'other';
        $copy = $value->type($typeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getType());
        $this->assertNotEquals('other', $value->getType());
        $this->assertEquals('one', $value->getTypeOrCurrent(TemplateVariableTypeVO::from($typeOtherValue))->value());
        $this->assertNotEquals('other', $value->getTypeOrCurrent(TemplateVariableTypeVO::from($typeOtherValue))->value());
        $value->unsetType();
        $this->assertEquals('other', $value->getTypeOrCurrent(TemplateVariableTypeVO::from($typeOtherValue))->value());
        $this->assertNotEquals('one', $value->getTypeOrCurrent(TemplateVariableTypeVO::from($typeOtherValue))->value());
        $valueOneValue = 'one';
        $valueOtherValue = 'other';
        $copy = $value->value($valueOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getValue());
        $this->assertNotEquals('other', $value->getValue());
        $this->assertEquals('one', $value->getValueOrCurrent(TemplateVariableValueVO::from($valueOtherValue))->value());
        $this->assertNotEquals('other', $value->getValueOrCurrent(TemplateVariableValueVO::from($valueOtherValue))->value());
        $value->unsetValue();
        $this->assertEquals('other', $value->getValueOrCurrent(TemplateVariableValueVO::from($valueOtherValue))->value());
        $this->assertNotEquals('one', $value->getValueOrCurrent(TemplateVariableValueVO::from($valueOtherValue))->value());
        $enabledOneValue = true;
        $enabledOtherValue = false;
        $copy = $value->enabled($enabledOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isEnabled());
        $this->assertNotEquals(false, $value->isEnabled());
        $this->assertEquals(true, $value->getEnabledOrCurrent(TemplateVariableEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(false, $value->getEnabledOrCurrent(TemplateVariableEnabledVO::from($enabledOtherValue))->value());
        $value->unsetEnabled();
        $this->assertEquals(false, $value->getEnabledOrCurrent(TemplateVariableEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(true, $value->getEnabledOrCurrent(TemplateVariableEnabledVO::from($enabledOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(TemplateVariableVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(TemplateVariableVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(TemplateVariableVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(TemplateVariableVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
